this.changeNewExpiryDate = function () {

	if (this.context.binding.get("value").get("LGExpiryPeriodType")!= "FIXED") {
		return ;
	}
	var contractDate = new Date(this.context.binding.get("value").get("currentExpiryDate").toString());
	var newExpiryDate = new Date(this.context.binding.get("value").get("newExpiryDate").toString());
	var diffrence = newExpiryDate.getTime() - contractDate.getTime() ;
	diffrence = diffrence / (1000*60*60*24) ;
	if(this.context.binding.get("value").get("expiryType") != "days"){	
		this.context.binding.get("value").set("expiryType", {name:"Days / ايام" , value:"days"})
	}
	if(this.context.binding.get("value").get("periodExpiryDate") != ( Math.ceil(diffrence)+1)){	
		this.context.binding.get("value").set("periodExpiryDate" , Math.ceil(diffrence)+1);
	}
}
this.calculateExpryDate = function() {
	if (this.context.binding.get("value").get("LGExpiryPeriodType")!= "PRIOD") {
		return ;
	}
	var periodType = this.context.binding.get("value").get("expiryType").get("value"); 
	var periodExpiryDate = this.context.binding.get("value").get("periodExpiryDate");
	var contractDate = new Date(this.context.binding.get("value").get("currentExpiryDate").toString());
	contractDate.setDate(contractDate.getDate() -  1);// why we do this ??	bussiness user asked for that in lg issuance
	if (!!periodExpiryDate && !!periodType) {
		var result = calculateDays(periodType , periodExpiryDate , contractDate);
		this.context.binding.get("value").set("newExpiryDate",result);
	}
}
function calculateDays(periodType , periodExpiryDate , contractDate)
{
	if(periodType == "days")  {
		contractDate.setDate(contractDate.getDate() + periodExpiryDate);	
	}
	else if(periodType == "months")  {
		contractDate.setMonth(contractDate.getMonth() + periodExpiryDate);		
	}
	else if(periodType == "years")  {
		contractDate.setFullYear(contractDate.getFullYear() + periodExpiryDate);		
	}
	return contractDate;
}
