this.calculateNewOutsranding = function (){
	var increaseType = this.context.binding.get("value").get("IncreaseType");
	var amount = this.context.binding.get("value").get("amount");
	var changedAmount= this.context.binding.get("value").get("changedAmount");
	var total = 0;
	if (changedAmount < 0 ) {
		this.context.binding.get("value").set("newOutstandingAmount", 0);
		return "Invaid value , negative value isn't allowed" ;
	}
	if (!!increaseType && !!amount && !!changedAmount) {
		if (increaseType == "DEC") {
			total = amount - changedAmount;
			this.context.binding.get("value").set("newOutstandingAmount", total);
		} else if(increaseType == "INC") {
			total = amount + changedAmount;
			this.context.binding.get("value").set("newOutstandingAmount", total);
		}
	}
	return checkAmount(total);
}

