this.checkValue = function () {
	var length = 0;

//	this.context.options.AddBtnLabelName.set("value", "Create Folder - إنشاء ملف");
	var versionNo = (this.context.binding.get("value").toUpperCase()).replace("V" , ''); // new
	var maximumVersionNumber = this.context.options.maximumVersionNumber.get("value");
	
	if (versionNo != null && versionNo != "" && versionNo != "0") {
	
		var removeZero = 	versionNo.replace(/^0+/, '');
		versionNo = removeZero;		
	}
	if (parseInt(versionNo) > parseInt(maximumVersionNumber)) {
		this.context.binding.set("value", 0);
		return;
	}
	
	var checkIfSubFolder  = false;
	try{
	 checkIfSubFolder = (versionNo.indexOf("/") > -1)
	}
	catch(err){
		checkIfSubFolder = false;
	}
	if (checkIfSubFolder) {
		versionNo = versionNo.replace(' ',"");
		versionNo = "  " + versionNo;
	}
	
	try {
		length = this.context.options.availableFoldersList.get("value").length();
	} catch (err) {
		length = 0;
	}
	
	var currentItem ; 
	var dataChanged = false;
	for (var i=0; i<length; i++) {
		currentItem = this.context.options.availableFoldersList.get("value").get(i);
		if (versionNo == currentItem) {
			this.context.options.selectedVersion.set("value", versionNo);
			dataChanged = true;
			break;
		}
		else if("V"+versionNo == currentItem) {
			this.context.options.selectedVersion.set("value", "V"+versionNo);
			dataChanged = true;
			break;
		}
	}
	if (!dataChanged) {
		this.context.binding.set("value", "V"+versionNo)
	}
	
}

