this.changeVisibilty = function(val) {
    var vis = "NONE";
    if (val == "0") { // if no changes happened
        return;
    }
    this.context.binding.get("value").get("changeAccounts").set("UncoverSection", "NONE"); // un covered account

    this.context.options.AmendSectionsVisibilty.get("value").set("changeLGAmountVis", vis);
    this.context.options.AmendSectionsVisibilty.get("value").set("chengeExpiryDateVis", vis);
    this.context.options.AmendSectionsVisibilty.get("value").set("changeAccountsVis", vis);
    this.context.options.AmendSectionsVisibilty.get("value").set("ChangeFacilityVis", vis);
    this.context.options.AmendSectionsVisibilty.get("value").set("changeLGOrderingAccounteeVis", vis);
    this.context.options.AmendSectionsVisibilty.get("value").set("NatureOfLGVis", vis);
    this.context.options.AmendSectionsVisibilty.get("value").set("orderingApplicantInformationVis", vis);
    this.context.options.AmendSectionsVisibilty.get("value").set("beneficiaryVis", vis);
    this.context.options.AmendSectionsVisibilty.get("value").set("correspondentVis", vis);
    this.context.options.AmendSectionsVisibilty.get("value").set("activationVis", vis);
    this.context.options.AmendSectionsVisibilty.get("value").set("LGPurposeVis", vis);
    this.context.options.AmendSectionsVisibilty.get("value").set("changeLGLiquidation", vis);
    this.context.options.AmendSectionsVisibilty.get("value").set("chargesVis", vis);

    //	this.context.options.AmendSectionsVisibilty.get("value").set("basicInfoVis",vis);
    //	this.context.options.AmendSectionsVisibilty.get("value").set("LGforTheAccountInformationVis",vis);
    //	this.context.options.AmendSectionsVisibilty.get("value").set("recommendedApprovalsVis",vis);
    vis = "Default";

    this.context.options.AmendSectionsVisibilty.get("value").set("LGforTheAccountInformationVis", vis); // pending questions
    if (val == "Liquidation") {
        this.context.options.AmendSectionsVisibilty.get("value").set("changeAccountsVis", vis);
        this.context.options.AmendSectionsVisibilty.get("value").set("changeLGLiquidation", vis);
        if (this.context.binding.get("value").get("LGBasicInformation").get("contractDetails").get("Contract_Limits").length() > 0) {
            this.context.binding.get("value").get("changeAccounts").set("UncoverSection", "Default");
        } else {
            this.context.binding.get("value").get("changeAccounts").set("UncoverSection", "NONE");
        }

    }

    if (this.context.binding.get("value").get("amendmentOptions").get("chengeOptions").get("activeLG")) {
        this.context.options.AmendSectionsVisibilty.get("value").set("activationVis", vis);
		this.context.options.AmendSectionsVisibilty.get("value").set("chargesVis", vis);

    }
    if (this.context.binding.get("value").get("amendmentOptions").get("chengeOptions").get("changeLGAmount")) {
        this.context.options.AmendSectionsVisibilty.get("value").set("changeLGAmountVis", vis);
		this.context.options.AmendSectionsVisibilty.get("value").set("chargesVis", vis);
    }
    if (this.context.binding.get("value").get("amendmentOptions").get("chengeOptions").get("changeLGNature")) {
        this.context.options.AmendSectionsVisibilty.get("value").set("NatureOfLGVis", vis);
		this.context.options.AmendSectionsVisibilty.get("value").set("chargesVis", vis);
		this.context.binding.get("value").get("recommendedApprovals").set("CADVis", vis);
        if (this.context.binding.get("value").get("NatureOfLG") == "التعديل الي تسهيلات ائتمانية") {
            this.context.options.AmendSectionsVisibilty.get("value").set("changeAccountsVis", vis);
            this.context.options.AmendSectionsVisibilty.get("value").set("ChangeFacilityVis", vis);
        } else if (this.context.binding.get("value").get("NatureOfLG") == "التعديل الي غطاء نقدي بالكامل") {
            this.context.options.AmendSectionsVisibilty.get("value").set("changeAccountsVis", vis);
            this.context.options.AmendSectionsVisibilty.get("value").set("ChangeFacilityVis", "NONE");
            this.context.binding.get("value").get("amendmentOptions").get("chengeOptions").set("changeFacility", false)
            this.context.binding.get("value").get("ChangeFacility").set("CashCover", 100)            
        }
    }
    if (this.context.binding.get("value").get("amendmentOptions").get("chengeOptions").get("changeAccount")) {
        this.context.options.AmendSectionsVisibilty.get("value").set("changeAccountsVis", vis);
		this.context.options.AmendSectionsVisibilty.get("value").set("chargesVis", vis);
    
	}
    if (this.context.binding.get("value").get("amendmentOptions").get("chengeOptions").get("changeOrderingAcc")) {
        this.context.options.AmendSectionsVisibilty.get("value").set("changeLGOrderingAccounteeVis", vis);
		this.context.options.AmendSectionsVisibilty.get("value").set("chargesVis", vis);
    }
    if (this.context.binding.get("value").get("amendmentOptions").get("chengeOptions").get("changeBeneficiary")) {
        this.context.options.AmendSectionsVisibilty.get("value").set("beneficiaryVis", vis);
//        this.context.options.AmendSectionsVisibilty.get("value").set("ChangeFacilityVis", vis);
	  this.context.options.AmendSectionsVisibilty.get("value").set("chargesVis", vis);
		
    }
    if (this.context.binding.get("value").get("amendmentOptions").get("chengeOptions").get("changeFacility")) {
        this.context.options.AmendSectionsVisibilty.get("value").set("ChangeFacilityVis", vis);
		this.context.options.AmendSectionsVisibilty.get("value").set("chargesVis", vis);
		
		
    }
    if (this.context.binding.get("value").get("amendmentOptions").get("chengeOptions").get("LGLiquidation")) {
        this.context.options.AmendSectionsVisibilty.get("value").set("changeAccountsVis", vis);
        this.context.options.AmendSectionsVisibilty.get("value").set("changeLGLiquidation", vis);
	  this.context.options.AmendSectionsVisibilty.get("value").set("chargesVis", vis);
		
        if (this.context.binding.get("value").get("LGBasicInformation").get("contractDetails").get("Contract_Limits").length() > 0) {
            this.context.binding.get("value").get("changeAccounts").set("UncoverSection", "Default");
        } else {
            this.context.binding.get("value").get("changeAccounts").set("UncoverSection", "NONE");
        }    
    }
    if (this.context.binding.get("value").get("amendmentOptions").get("chengeOptions").get("reopenLG")) {
		
    }
    if (this.context.binding.get("value").get("amendmentOptions").get("chengeOptions").get("extendLG")) {
        this.context.options.AmendSectionsVisibilty.get("value").set("chengeExpiryDateVis", vis);
		this.context.options.AmendSectionsVisibilty.get("value").set("chargesVis", vis);

    }
    if (this.context.binding.get("value").get("amendmentOptions").get("chengeOptions").get("changeLGpurpose")) {
        this.context.options.AmendSectionsVisibilty.get("value").set("LGPurposeVis", vis);
		this.context.options.AmendSectionsVisibilty.get("value").set("chargesVis", vis);
		
    }
	if ((this.context.binding.get("value").get("amendmentOptions").get("chengeOptions").get("changeLGNature") &&
		this.context.binding.get("value").get("NatureOfLG") == "التعديل الي تسهيلات ائتمانية" )|| 
		this.context.binding.get("value").get("amendmentOptions").get("chengeOptions").get("changeFacility") || 
		this.context.binding.get("value").get("LGBasicInformation").get("contractDetails").get("Contract_Limits").length() > 0)
	{
		this.context.binding.get("value").get("recommendedApprovals").set("CADVis", "default");
	}
	else
	{
		this.context.binding.get("value").get("recommendedApprovals").set("CADVis", "Readonly");
		this.context.binding.get("value").get("recommendedApprovals").set("CAD", false);
	}
	this.context.options.ValuesChanges.set("value", "0");
}

